using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class RotateStandaloneSkill03{
 public static object Run(){if(Application.isPlaying)throw new Exception("Stop play first");var live=GameObject.Find("Attack 05 - Skill_03");var a=live.GetComponentInChildren<Animator>();var clip=a.runtimeAnimatorController.animationClips[0];var combo=GameObject.Find("New Knight Combo Sequence Preview").GetComponentInChildren<Animator>().runtimeAnimatorController.animationClips[0];string comboBefore=EditorJsonUtility.ToJson(combo);string path=AssetDatabase.GetAssetPath(clip),backup=path.Replace(".anim","_BeforeUniform90.anim");if(AssetDatabase.LoadAssetAtPath<AnimationClip>(backup)==null)AssetDatabase.CopyAsset(path,backup);var source=AssetDatabase.LoadAssetAtPath<AnimationClip>(backup);var root=UnityEngine.Object.Instantiate(live);root.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);try{var ca=root.GetComponentInChildren<Animator>();ca.enabled=false;var hip=root.GetComponentsInChildren<Transform>().First(t=>t.name=="Hips");string hp=AnimationUtility.CalculateTransformPath(hip,ca.transform);source.SampleAnimation(ca.gameObject,0);var pivot=hip.position;var correction=Quaternion.AngleAxis(-90,Vector3.up);int frames=Mathf.RoundToInt(source.length*240);var keys=Enumerable.Range(0,7).Select(_=>new Keyframe[frames+1]).ToArray();Quaternion previous=Quaternion.identity;for(int i=0;i<=frames;i++){float t=source.length*i/frames;source.SampleAnimation(ca.gameObject,t);hip.SetPositionAndRotation(pivot+correction*(hip.position-pivot),correction*hip.rotation);var p=hip.localPosition;var q=hip.localRotation;if(i>0&&Quaternion.Dot(previous,q)<0)q=new Quaternion(-q.x,-q.y,-q.z,-q.w);previous=q;for(int c=0;c<7;c++)keys[c][i]=new Keyframe(t,c<3?p[c]:q[c-3]);}Undo.RecordObject(clip,"Rotate standalone skill3 uniformly");for(int c=0;c<7;c++){var curve=new AnimationCurve(keys[c]);for(int i=0;i<curve.length;i++){AnimationUtility.SetKeyLeftTangentMode(curve,i,AnimationUtility.TangentMode.Linear);AnimationUtility.SetKeyRightTangentMode(curve,i,AnimationUtility.TangentMode.Linear);}AnimationUtility.SetEditorCurve(clip,EditorCurveBinding.FloatCurve(hp,typeof(Transform),c<3?"m_LocalPosition."+"xyz"[c]:"m_LocalRotation."+"xyzw"[c-3]),curve);}float error=0;for(int f=0;f<=16;f++){source.SampleAnimation(ca.gameObject,f/30f);var expected=correction*hip.rotation;clip.SampleAnimation(ca.gameObject,f/30f);error=Mathf.Max(error,Quaternion.Angle(expected,hip.rotation));}EditorUtility.SetDirty(clip);clip.SampleAnimation(a.gameObject,0);AssetDatabase.SaveAssets();var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);return new{rotation=-90,firstFrame=0,lastFrame=16,maxRotationError=error,comboUnchanged=comboBefore==EditorJsonUtility.ToJson(combo)};}finally{UnityEngine.Object.DestroyImmediate(root);}}
}
